--
-- Table structure for table `match_tickets`
--

DROP TABLE IF EXISTS `match_tickets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `match_tickets` (
  `ticket_id` int NOT NULL AUTO_INCREMENT,
  `party_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `mode` int NOT NULL,
  `mode_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'duels',
  `mode_variant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `map` int NOT NULL,
  `size` tinyint NOT NULL,
  `mmr` int NOT NULL,
  `team1_count` tinyint NOT NULL DEFAULT '0',
  `team2_count` tinyint NOT NULL DEFAULT '0',
  `status` enum('queued','cancelled') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'queued',
  `claimed_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ticket_id`),
  UNIQUE KEY `party_id` (`party_id`),
  UNIQUE KEY `user_id` (`user_id`),
  KEY `idx_match_tickets_queue_bucket` (`status`,`mode_id`,`mode_variant_id`,`map`,`created_at`),
  CONSTRAINT `fk_mt_party` FOREIGN KEY (`party_id`) REFERENCES `parties` (`party_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_mt_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3474 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

